use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
}

impl Tree {
    fn insert(self, x: int) -> bool {
        if self.root == -1 {
            self.keys.push(x)
            self.left.push(-1)
            self.right.push(-1)
            self.root = 0
            return true
        }
        let mut cur: int = self.root
        loop {
            let k = self.keys[cur]
            if x == k {
                return false
            }
            let next: int = if x < k { self.left[cur] } else { self.right[cur] }
            if next == -1 {
                let id: int = self.keys.len() as int
                self.keys.push(x)
                self.left.push(-1)
                self.right.push(-1)
                if x < k {
                    self.left[cur] = id
                } else {
                    self.right[cur] = id
                }
                return true
            }
            cur = next
        }
    }

    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            cur = if x < k { self.left[cur] } else { self.right[cur] }
        }
        false
    }

    fn replace_child(self, p: int, old: int, new: int) {
        if p == -1 {
            self.root = new
        } else if self.left[p] == old {
            self.left[p] = new
        } else {
            self.right[p] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut cur: int = self.root
        let mut par: int = -1
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                break
            }
            par = cur
            cur = if x < k { self.left[cur] } else { self.right[cur] }
        }
        if cur == -1 {
            return false
        }
        if self.left[cur] != -1 && self.right[cur] != -1 {
            let mut sp: int = cur
            let mut s: int = self.right[cur]
            while self.left[s] != -1 {
                sp = s
                s = self.left[s]
            }
            self.keys[cur] = self.keys[s]
            let rc: int = self.right[s]
            self.replace_child(sp, s, rc)
        } else {
            let child: int = if self.left[cur] != -1 { self.left[cur] } else { self.right[cur] }
            self.replace_child(par, cur, child)
        }
        true
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur: int = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.left[cur]
            }
            let n: int = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n]}")
            cur = self.right[n]
        }
        if out.len() == 0 {
            return "<empty>"
        }
        out.join(" ")
    }

    fn height(self) -> int {
        if self.root == -1 {
            return 0
        }
        let mut level: Vec<int> = [self.root]
        let mut h: int = 0
        while level.len() > 0 {
            h += 1
            let mut nxt: Vec<int> = []
            for n in level {
                if self.left[n] != -1 {
                    nxt.push(self.left[n])
                }
                if self.right[n] != -1 {
                    nxt.push(self.right[n])
                }
            }
            level = nxt
        }
        h
    }

    fn min(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.left[cur] != -1 {
            cur = self.left[cur]
        }
        "${self.keys[cur]}"
    }

    fn max(self) -> string {
        if self.root == -1 {
            return "empty"
        }
        let mut cur: int = self.root
        while self.right[cur] != -1 {
            cur = self.right[cur]
        }
        "${self.keys[cur]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            println(t.min())
        } else if cmd == "max" {
            println(t.max())
        }
    }
}

